INSERT INTO crop_catalog (crop_id, name, growth_days, planting_guide, created_at, updated_at) VALUES
('50000000-0000-0000-0000-000000000004', 'Dâu tây', 120, 'Trồng cây con trên luống có phủ màng, tưới nhỏ giọt, ngắt bỏ lá già và thu hoạch khi quả chín đỏ 80%.', '2026-01-05 08:00:00+07', '2026-01-05 08:00:00+07'),
('50000000-0000-0000-0000-000000000005', 'Bắp cải', 75, 'Trồng cây con khoảng cách 40x40cm, bón lót phân hữu cơ, theo dõi sâu tơ định kỳ.', '2026-01-05 08:00:00+07', '2026-01-05 08:00:00+07'),
('50000000-0000-0000-0000-000000000006', 'Su hào', 60, 'Gieo ươm 15 ngày rồi đánh ra luống, giữ ẩm đều để củ không nứt.', '2026-01-05 08:00:00+07', '2026-01-05 08:00:00+07'),
('50000000-0000-0000-0000-000000000007', 'Cà rốt', 90, 'Gieo thẳng trên luống cao, tỉa cây khi có 3-4 lá thật, không bón phân tươi.', '2026-01-05 08:00:00+07', '2026-01-05 08:00:00+07'),
('50000000-0000-0000-0000-000000000008', 'Dưa leo', 50, 'Làm giàn cao 1.8m, bấm ngọn khi cây đạt 2m, thu hoạch mỗi 2 ngày.', '2026-01-05 08:00:00+07', '2026-01-05 08:00:00+07'),
('50000000-0000-0000-0000-000000000009', 'Ớt chuông', 100, 'Trồng trong nhà màng, giàn đỡ từng cây, bón kali nuôi quả.', '2026-01-05 08:00:00+07', '2026-01-05 08:00:00+07'),
('50000000-0000-0000-0000-000000000010', 'Rau muống', 25, 'Gieo dày, giữ nước ngập nhẹ, thu hoạch khi cây cao 30cm.', '2026-01-05 08:00:00+07', '2026-01-05 08:00:00+07'),
('50000000-0000-0000-0000-000000000011', 'Lúa OM 5451', 100, 'Sạ hàng, giữ mực nước 3-5cm, bón 3 đợt theo giai đoạn đẻ nhánh, làm đòng, trổ bông.', '2026-01-05 08:00:00+07', '2026-01-05 08:00:00+07'),
('50000000-0000-0000-0000-000000000012', 'Khoai tây', 90, 'Trồng củ giống đã nảy mầm, vun gốc 2 lần, ngừng tưới 10 ngày trước thu hoạch.', '2026-01-05 08:00:00+07', '2026-01-05 08:00:00+07'),
('50000000-0000-0000-0000-000000000013', 'Cải thìa', 35, 'Gieo hạt trên luống, tưới phun sương, thu hoạch khi cây cao 20cm.', '2026-01-05 08:00:00+07', '2026-01-05 08:00:00+07');
